package br.edu.scoa.academico.infraestrutura.persistencia;
import br.edu.scoa.academico.aplicacao.matriculas.*;import br.edu.scoa.academico.dominio.matriculas.*;import java.sql.*;import java.time.*;import java.util.*;
public final class RepositorioMatriculasMysql implements RepositorioMatriculas {private final ConfiguracaoBanco banco;public RepositorioMatriculasMysql(ConfiguracaoBanco b){banco=b;}public MatriculaCurso salvar(MatriculaCurso m,UUID op,long autor,Instant instante){try(var c=banco.abrir()){try(var s=c.prepareStatement("INSERT INTO matricula_curso(numero_matricula,aluno_id,curso_id,matriz_id,data_ingresso,situacao,versao_registro,operacao_criacao) VALUES(?,?,?,?,?,?,1,?)",Statement.RETURN_GENERATED_KEYS)){s.setString(1,m.numeroMatricula());s.setLong(2,m.alunoId());s.setLong(3,m.cursoId());s.setLong(4,m.matrizId());s.setObject(5,m.dataIngresso());s.setString(6,m.situacao().name());s.setString(7,op.toString());s.executeUpdate();try(var r=s.getGeneratedKeys()){r.next();return m.identificado(r.getLong(1),1);}}}catch(SQLException e){throw new FalhaMatricula(e.getErrorCode()==1062?FalhaMatricula.Codigo.MATRICULA_INVALIDA:FalhaMatricula.Codigo.NAO_ENCONTRADO);}}public Optional<MatriculaCurso> porNumero(String n){return buscar("numero_matricula",n);}public Optional<MatriculaCurso> consultar(long id){return buscar("id",id);}private Optional<MatriculaCurso> buscar(String campo,Object valor){try(var c=banco.abrir();var s=c.prepareStatement("SELECT * FROM matricula_curso WHERE "+campo+"=?")){s.setObject(1,valor);try(var r=s.executeQuery()){return r.next()?Optional.of(ler(r)):Optional.empty();}}catch(SQLException e){throw new FalhaMatricula(FalhaMatricula.Codigo.NAO_ENCONTRADO);}}public List<MatriculaCurso> porAluno(long aluno){var itens=new ArrayList<MatriculaCurso>();try(var c=banco.abrir();var s=c.prepareStatement("SELECT * FROM matricula_curso WHERE aluno_id=? ORDER BY id")){s.setLong(1,aluno);try(var r=s.executeQuery()){while(r.next())itens.add(ler(r));}return List.copyOf(itens);}catch(SQLException e){throw new FalhaMatricula(FalhaMatricula.Codigo.NAO_ENCONTRADO);}}private MatriculaCurso ler(ResultSet r)throws SQLException{return new MatriculaCurso(r.getLong("id"),r.getString("numero_matricula"),r.getLong("aluno_id"),r.getLong("curso_id"),r.getLong("matriz_id"),r.getObject("data_ingresso",LocalDate.class),SituacaoMatricula.valueOf(r.getString("situacao")),r.getLong("versao_registro"));}}
